<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sampler FX · LT10</title><style>
:root{--bg:#16191f;--panel:#252a33;--panel2:#303641;--text:#f1f4f5;--muted:#a7b0bd;--aqua:#55dccb;--pink:#f587b2;--violet:#ad90e8;--blue:#77b5ee;--orange:#f7aa6a;--red:#ef6b75}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,-apple-system,"Segoe UI",Arial,sans-serif}.bar{height:68px;padding:8px 16px;display:flex;align-items:center;gap:9px;background:#191d24;border-bottom:1px solid #343a45;position:sticky;top:0;z-index:4}.home,.control{height:51px;border:0;border-radius:4px;background:#303641;color:var(--text);padding:0 16px;font:inherit;font-weight:700;cursor:pointer}.home{font-size:21px}.title{height:51px;min-width:220px;display:flex;align-items:center;padding:0 18px;background:#740050;font-size:16px;font-weight:800;letter-spacing:.04em}.spacer{flex:1}.toggle{display:flex;align-items:center;gap:9px}.toggle input{accent-color:var(--aqua);width:19px;height:19px}.record{background:#3a404c}.record.active{background:#b9415d;color:#fff}.key{min-width:92px}.status{color:var(--muted);font-size:12px;max-width:300px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pad-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(132px,1fr));gap:7px;padding:16px}.pad{height:128px;border:0;border-radius:4px;text-align:left;padding:10px;color:#ecf6f4;background:#214e55;position:relative;cursor:pointer;overflow:hidden}.pad:nth-child(6n+2){background:#64343e}.pad:nth-child(6n+3){background:#55434b}.pad:nth-child(6n+4){background:#315846}.pad:nth-child(6n+5){background:#68405f}.pad:nth-child(6n){background:#274b70}.pad:hover,.pad.selected{outline:2px solid var(--aqua);outline-offset:1px}.pad.playing{box-shadow:inset 0 0 0 3px var(--aqua);filter:brightness(1.17)}.pos{position:absolute;top:8px;left:9px;color:#d6e0e0;font-size:11px}.shortcut{position:absolute;top:8px;right:34px;background:#1118;border-radius:3px;padding:2px 5px;font-size:11px}.play-ring{position:absolute;left:10px;bottom:10px;width:39px;height:39px;border-radius:50%;padding:2px;background:conic-gradient(var(--aqua) calc(var(--progress,0) * 1%),rgb(255 255 255 / 22%) 0)}.play{width:35px;height:35px;border-radius:50%;border:0;background:#fff;color:#1d2530;font-size:15px;cursor:pointer}.pad.playing .play{background:var(--aqua)}.name{position:absolute;left:58px;right:9px;bottom:28px;font-size:13px;font-weight:700;line-height:1.2;max-height:33px;overflow:hidden}.time{position:absolute;left:58px;right:9px;bottom:12px;color:#d9e7e6;font-size:10px;font-variant-numeric:tabular-nums}.loading{color:var(--muted);text-align:center;padding:24px;display:flex;flex-direction:column;align-items:center;gap:10px}.load-more{background:var(--panel2);border:1px solid #586270;color:#fff;border-radius:5px;padding:10px 20px;font:inherit;font-weight:700;cursor:pointer}.load-more:hover{border-color:var(--aqua)}.load-more:disabled{opacity:.45;cursor:default}.pad-fixed{position:absolute;top:7px;right:8px;display:grid;place-items:center;width:19px;height:19px;cursor:pointer}.pad-fixed input{width:15px;height:15px;accent-color:var(--aqua);cursor:pointer}.pad-top{position:absolute;right:9px;bottom:10px;width:29px;height:29px;border:1px solid rgb(255 255 255 / 45%);border-radius:50%;background:#1115;color:#fff;font-size:18px;line-height:1;cursor:pointer}.pad-top:hover{border-color:var(--aqua);color:var(--aqua)}.pad.fixed{outline:2px solid #fff;outline-offset:-4px}.quick-search{height:40px;width:190px;border:1px solid #586270;border-radius:4px;background:#20252e;color:#fff;padding:0 11px;font:inherit}.pad.dragging{opacity:.45}.pad.drag-over{outline:3px dashed var(--aqua);outline-offset:2px}.context{position:fixed;display:none;z-index:8;background:#353b46;border:1px solid #59616e;border-radius:5px;box-shadow:0 8px 30px #0008;min-width:190px}.context button{display:block;width:100%;padding:10px 13px;text-align:left;border:0;background:transparent;color:#fff;cursor:pointer}.context button:hover{background:#4a5360}@media(max-width:650px){.bar{height:auto;flex-wrap:wrap;padding:8px}.title{min-width:0;flex:1}.spacer{display:none}.status{order:3;flex-basis:100%}.pad-grid{grid-template-columns:repeat(2,minmax(0,1fr));padding:8px}.pad{height:112px}.control{padding:0 10px}}
</style></head><body><header class="bar"><button class="home" onclick="location.href='index.php'" aria-label="Volver a Discoteca">⌂</button><div class="title">SAMPLER FX</div><label class="control toggle"><input type="checkbox" id="loop">Loop</label><button class="control key" id="keyButton">Key</button><button class="control record" id="recordButton">● Rec</button><input id="quickSearch" class="quick-search" type="search" placeholder="Buscar rápido…" aria-label="Buscar sampler"><span class="spacer"></span><span class="status" id="status">Cargando efectos…</span></header><main id="pads" class="pad-grid"></main><div class="loading" id="loading"><button id="loadMore" class="load-more" type="button">Cargar más</button><span id="loadState">Cargando sampler…</span></div><nav class="context" id="context"><button data-action="top">Enviar al inicio</button><button data-action="bottom">Enviar al final</button><button data-action="position">Indicar posición…</button></nav><audio id="audio" preload="metadata"></audio><script>
const pads=document.getElementById('pads'),audio=document.getElementById('audio'),statusEl=document.getElementById('status'),context=document.getElementById('context'),loop=document.getElementById('loop');let offset=0,total=0,loading=false,selected=null,playing=null,recordMode=false,dragged=null,manualLoaded=false;audio.loop=false;loop.onchange=()=>audio.loop=loop.checked;
function fmt(s){s=isFinite(s)?Math.floor(s):0;return Math.floor(s/60)+':'+('0'+s%60).slice(-2)}function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function render(item){const b=document.createElement('article');b.className='pad';b.dataset.id=item.id;b.dataset.position=item.posicion;b.innerHTML='<span class="pos">#'+item.posicion+'</span><span class="shortcut">'+(item.atajo||'—')+'</span><label class="pad-fixed" title="Fijar este sampler"><input class="lock" type="checkbox" '+(Number(item.fijado)===1?'checked':'')+'></label><span class="play-ring"><button class="play" aria-label="Reproducir">▶</button></span><span class="name">'+esc(item.titulo)+'</span><span class="time">—</span><button class="pad-top" title="Enviar a posición 1">↑</button>';b.draggable=Number(item.fijado)!==1;if(Number(item.fijado)===1)b.classList.add('fixed');b.ondragstart=e=>{if(Number(item.fijado)===1){e.preventDefault();statusEl.textContent='Este sampler está fijado';return}dragged={item,el:b};select(item,b);b.classList.add('dragging');e.dataTransfer.effectAllowed='move'};b.ondragend=()=>b.classList.remove('dragging');b.ondragover=e=>{e.preventDefault();b.classList.add('drag-over')};b.ondragleave=()=>b.classList.remove('drag-over');b.ondrop=e=>{e.preventDefault();b.classList.remove('drag-over');if(dragged&&dragged.item.id!==item.id){selected=dragged;action('position',item.posicion)};dragged=null};b.onclick=e=>{if(e.target.closest('.play'))play(item,b);else if(e.target.closest('.pad-top')){select(item,b);if(Number(item.fijado)===1)statusEl.textContent='Este sampler está fijado';else action('top')}else select(item,b)};b.onchange=e=>{if(!e.target.closest('.lock'))return;const fijado=e.target.checked?1:0;fetch('sampler_fx_action.php',{method:'POST',body:new URLSearchParams({action:'set_fixed',tema_id:item.id,fijado})}).then(r=>r.json()).then(d=>{if(d.ok){item.fijado=fijado;b.draggable=!fijado;b.classList.toggle('fixed',!!fijado);statusEl.textContent=fijado?'Sampler fijado':'Sampler liberado'}})};b.oncontextmenu=e=>{e.preventDefault();select(item,b);context.style.display='block';context.style.left=e.clientX+'px';context.style.top=e.clientY+'px'};pads.appendChild(b)}
function select(item,el){document.querySelectorAll('.pad.selected').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');selected={item,el};statusEl.textContent='#'+item.posicion+' · '+item.titulo+(Number(item.fijado)===1?' · fijo':'')+(item.atajo?' · tecla '+item.atajo:'')}function select(item,el){document.querySelectorAll('.pad.selected').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');selected={item,el};const fixed=document.getElementById('fixedToggle'),top=document.getElementById('keyButton').onclick=()=>{if(!selected){statusEl.textContent='Seleccioná un sampler primero';return}const k=prompt('Atajo para '+selected.item.titulo+' (A-Z o 0-9, vacío para quitar)',selected.item.atajo||'');if(k!==null){fetch('sampler_fx_action.php',{method:'POST',body:new URLSearchParams({action:'assign_key',tema_id:selected.item.id,atajo:k})}).then(()=>{selected.el.querySelector('.shortcut').textContent=k.toUpperCase()||'—';selected.item.atajo=k.toUpperCase();statusEl.textContent='Atajo actualizado'})}};document.getElementById('recordButton').onclick=e=>{recordMode=!recordMode;e.currentTarget.classList.toggle('active',recordMode);statusEl.textContent=recordMode?'REC activo: seleccioná un pad y luego otro para intercambiar':'REC desactivado'};let swapFirst=null;pads.addEventListener('click',e=>{if(!recordMode||!e.target.closest('.pad'))return;const el=e.target.closest('.pad'),item={id:el.dataset.id,position:el.dataset.position};if(!swapFirst){swapFirst=item;statusEl.textContent='REC: elegí el sampler que intercambiará con #'+item.position}else if(swapFirst.id!==item.id){selected={item:swapFirst,el:document.querySelector('.pad[data-id="'+swapFirst.id+'"]')};action('swap',item.id);swapFirst=null;recordMode=false;document.getElementById('recordButton').classList.remove('active')}});document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea'))return;const k=e.key.toUpperCase();const el=[...document.querySelectorAll('.pad')].find(x=>x.querySelector('.shortcut').textContent===k);if(el){el.querySelector('.play').click();e.preventDefault()}});load();
</script></body></html>
